import { Box } from '@mui/material';
import type { FC } from 'react';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';

/**
 * Markdown generated by AI is untrusted. Keep it on ReactMarkdown's safe defaults:
 * no Handlebars, raw HTML plugin, custom code-fence extensions, or remote images.
 */
const AiTriageMarkdown: FC<{ md: string }> = ({ md }) => (
  <Box sx={{ overflowWrap: 'anywhere', '& pre': { overflowX: 'auto' }, '& img': { display: 'none' } }}>
    <ReactMarkdown
      remarkPlugins={[remarkGfm]}
      components={{
        img: () => null
      }}
    >
      {md}
    </ReactMarkdown>
  </Box>
);

export default AiTriageMarkdown;
